/* The rail is the view-timeline subject (it is as tall as its section); the bar inside it moves
   from the top of the rail to the bottom while the section crosses the window. */
.growthbook-rail {
  view-timeline-name: --growthbook-rail;
}

.growthbook-rail-bar {
  height: min(25rem, 70%);
  background: linear-gradient(
    to bottom,
    transparent,
    var(--foreground) 6%,
    var(--primary) 15%,
    var(--glow) 22%,
    var(--card) 30%,
    var(--chart-2) 50%,
    var(--foreground) 62%,
    var(--highlight) 84%,
    var(--accent) 94%,
    transparent
  );
}

.growthbook-rail[data-fixed] .growthbook-rail-bar {
  height: 100%;
}

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .growthbook-rail:not([data-fixed]) .growthbook-rail-bar {
      animation: growthbook-rail-travel linear both;
      animation-timeline: --growthbook-rail;
      animation-range: cover 15% cover 85%;
    }
  }
}

@keyframes growthbook-rail-travel {
  from {
    top: 0;
  }
  to {
    top: calc(100% - min(25rem, 70%));
  }
}

import { cn } from "@foundry/foundry-utils";
import "./growthbook-rail.css";

export interface GrowthbookRailProps {
  /** which edge of the positioned parent it rides */
  side?: "left" | "right";
  /** fixed: the gradient fills the whole edge and stays still (the card-edge variant) */
  fixed?: boolean;
  /** bar width in px-ish Tailwind classes, e.g. "w-[3px]" (default) */
  className?: string;
}

/** Decorative only (aria-hidden). Put it in a `relative` box. */
export function GrowthbookRail({ side = "left", fixed, className }: GrowthbookRailProps) {
  return (
    <span
      aria-hidden
      data-fixed={fixed ? "" : undefined}
      className={cn(
        "growthbook-rail pointer-events-none absolute inset-y-0 w-[3px] overflow-clip",
        side === "left" ? "-left-px" : "-right-px",
        className,
      )}
    >
      <span className="growthbook-rail-bar absolute inset-x-0 top-0 block" />
    </span>
  );
}
